define([],function(){const escapeHtml=value=>{const div=document.createElement("div");div.textContent=value;return div.innerHTML};const disableOnSubmit=(form,submit,text)=>{if(!form||!submit){return}form.addEventListener("submit",function(){submit.disabled=true;submit.textContent=text||submit.textContent})};return{init:function(){const input=document.getElementById("geniaicourse-files");const container=document.getElementById("geniaicourse-fileinstructions");const form=document.getElementById("geniaicourse-form");const submit=document.getElementById("geniaicourse-submit");if(!input||!container){return}input.addEventListener("change",function(){container.innerHTML="";Array.from(input.files).forEach(function(file,index){const card=document.createElement("div");card.className="geniaicourse-fileitem";card.innerHTML='<div class="geniaicourse-filename">'+escapeHtml(file.name)+"</div>"+'<input class="form-control" type="text" name="fileinstructions['+index+']" '+'placeholder="'+escapeHtml(input.dataset.instructionplaceholder||"")+'">';container.appendChild(card)})});disableOnSubmit(form,submit,submit?submit.dataset.analyzing:"")},initReview:function(){const form=document.getElementById("geniaicourse-create-form");const submit=document.getElementById("geniaicourse-create-submit");disableOnSubmit(form,submit,submit?submit.dataset.creating:"")}}});